<?php declare(strict_types=1); require_once __DIR__.'/../lib_auth.php'; require_login(); ?>
<div class="container-fluid px-2 px-md-3 py-3"><h3 class="font-weight-bold">Kunjungan IGD</h3><div id="igdAlert"></div><div class="card card-soft mb-3"><div class="card-body"><div class="form-row align-items-end"><div class="form-group col-md-2"><label>Tanggal Mulai</label><input id="igdStart" type="date" class="form-control" value="<?=date('Y-m-d')?>"></div><div class="form-group col-md-2"><label>Tanggal Akhir</label><input id="igdEnd" type="date" class="form-control" value="<?=date('Y-m-d')?>"></div><div class="form-group col-md-3"><label>Status</label><select id="igdStatus" multiple class="form-control"></select></div><div class="form-group col-md-3"><label>Cara Bayar</label><select id="igdBayar" multiple class="form-control"></select></div><div class="form-group col-md-2"><button id="igdApply" class="btn btn-primary">Terapkan</button></div></div></div></div><div class="card card-soft"><div class="card-body"><table id="igdTable" class="table table-striped table-bordered nowrap" style="width:100%"><thead><tr><th>No. RM</th><th>Nama Pasien</th><th>Tanggal Registrasi</th><th>Dokter</th><th>Cara Bayar</th><th>Status</th><th>AsKep</th><th>AsMed</th><th>Triase</th><th>Resep Dokter</th></tr></thead></table></div></div></div>
<script>document.addEventListener('DOMContentLoaded',()=>{const id=x=>document.getElementById(x),vals=x=>Array.from(id(x).selectedOptions).map(o=>o.value),loadOpt=async(url,el)=>{const j=await (await fetch(url)).json();id(el).innerHTML=(j||[]).map(o=>'<option value="'+o.value+'">'+o.label+'</option>').join('')};let t;function init(){t=$('#igdTable').DataTable({data:[],scrollX:true,columns:[{data:'no_rkm_medis'},{data:'nm_pasien'},{data:'tgl_registrasi'},{data:'nm_dokter'},{data:'cara_bayar'},{data:'status_igd'},{data:'askep'},{data:'asmed'},{data:'triase'},{data:'resep_dokter'}],language:{emptyTable:'Tidak ada data IGD'}});load();}async function load(){const b=new URLSearchParams({startDate:id('igdStart').value,endDate:id('igdEnd').value});vals('igdStatus').forEach(v=>b.append('status[]',v));vals('igdBayar').forEach(v=>b.append('caraBayar[]',v));const j=await (await fetch('api/igd-datatable.php',{method:'POST',body:b})).json();if(!j.ok){id('igdAlert').textContent=j.message;return}t.clear().rows.add(j.data).draw()}Promise.all([loadOpt('api/rajal-stts-list.php','igdStatus'),loadOpt('api/rajal-carabayar-list.php','igdBayar')]).then(init);id('igdApply').onclick=load});</script>
